using System.Buffers.Binary;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Meridian.Mediator.Caching;

namespace Meridian.Mediator.Caching.Tests;

public sealed class SerializationContractTests
{
    internal static CacheContractRegistry Registry(int schema = 1) => new CacheContractRegistry().RegisterContract("reply.v1", schema, TestJson.Default.Reply).RegisterContract("int.v1", 1, TestJson.Default.Int32).RegisterContract("nullable.v1", 1, TestJson.Default.NullableInt32);
    internal static CacheValueCodec Codec(int schema = 1, CacheProviderOptions? options = null) { var r = Registry(schema); return new(r, new JsonCacheValueSerializer(r), options); }
    [Fact] public void Cache_RoundTrip_Uses_Registered_JsonTypeInfo() { var a = Codec(); var b = Codec(); Assert.Equal(new Reply("real", 42), b.Decode(a.Encode(new Reply("real", 42), "reply.v1"))); }
    [Fact] public void Unknown_Contract_Is_Rejected_Before_Body() { var bytes = Frame("remote.unknown", 1, "secret"); Assert.Equal(CacheValueRejectionReason.UnknownContract, Assert.Throws<CacheValueDataException>(() => Codec().Decode(bytes)).Reason); }
    [Fact] public void Schema_Mismatch_Is_Rejected() { var bytes = Codec().Encode(new Reply("v", 1), "reply.v1"); Assert.Equal(CacheValueRejectionReason.SchemaMismatch, Assert.Throws<CacheValueDataException>(() => Codec(2).Decode(bytes)).Reason); }
    [Theory] [InlineData(0)] [InlineData(1)] [InlineData(5)] [InlineData(6)] [InlineData(7)] [InlineData(12)] public void Truncated_Frame_Is_Rejected(int length) { Assert.Throws<CacheValueDataException>(() => Codec().Decode(new byte[length])); }
    [Fact] public void Unsupported_Version_Is_Rejected() { var b = Frame("reply.v1", 1, "{}"); b[4] = 2; Assert.Equal(CacheValueRejectionReason.UnsupportedVersion, Assert.Throws<CacheValueDataException>(() => Codec().Decode(b)).Reason); }
    [Theory] [InlineData("")] [InlineData("System.String, System.Private.CoreLib")] [InlineData("ümlaut")] [InlineData("space id")] public void Registry_Rejects_Unstable_Id(string id) { Assert.Throws<ArgumentException>(() => new CacheContractRegistry().RegisterContract(id, 1, TestJson.Default.Reply)); }
    [Fact] public void Registry_Rejects_Conflicts_And_Freezes() { var r = Registry(); r.RegisterContract("reply.v1", 1, TestJson.Default.Reply); Assert.Throws<InvalidOperationException>(() => r.RegisterContract("other", 1, TestJson.Default.Reply)); Assert.Throws<InvalidOperationException>(() => r.RegisterContract("reply.v1", 2, TestJson.Default.Reply)); _ = new JsonCacheValueSerializer(r); Assert.Throws<InvalidOperationException>(() => r.RegisterContract("late", 1, TestJson.Default.String)); }
    [Fact] public void Expected_Contract_And_Local_Missing_Id_Are_Distinct() { var c = Codec(); var b = c.Encode(new Reply("v", 1), "reply.v1"); Assert.Equal(CacheValueRejectionReason.ContractMismatch, Assert.Throws<CacheValueDataException>(() => c.Decode(b, "int.v1")).Reason); Assert.Throws<InvalidOperationException>(() => c.Decode(b, "missing")); }
    [Fact] public void Malformed_Json_Is_Redacted_Data_Rejection() { var e = Assert.Throws<CacheValueDataException>(() => Codec().Decode(Frame("reply.v1", 1, "private secret"))); Assert.Equal(CacheValueRejectionReason.MalformedBody, e.Reason); Assert.Equal("Cache entry data was rejected.", e.Message); Assert.Null(e.InnerException); }
    [Fact] public void Known_Reference_And_Nullable_Nulls_Are_Replayable_Only_In_Codec() { var c = Codec(); Assert.Null(c.Decode(c.Encode(null, "reply.v1"), "reply.v1")); Assert.Null(c.Decode(c.Encode(null, "nullable.v1"), "nullable.v1")); Assert.Equal(12, c.Decode(c.Encode((int?)12, "nullable.v1"))); Assert.Throws<InvalidOperationException>(() => c.Encode(null, "int.v1")); Assert.Throws<CacheValueDataException>(() => c.Decode(Frame("int.v1", 1, "null"))); }
    [Fact] public void Entry_Limits_Apply_Before_Deserialize_And_To_Encode() { var c = Codec(options: new() { MaximumEntryBytes = 32 }); Assert.Equal(CacheValueRejectionReason.OversizedEntry, Assert.Throws<CacheValueDataException>(() => c.Decode(new byte[33])).Reason); Assert.Throws<InvalidOperationException>(() => c.Encode(new Reply(new string('a', 100), 1), "reply.v1")); }
    [Fact] public void Custom_Opaque_Body_Is_Substitutable_And_Programming_Faults_Propagate() { var r = Registry(); var s = new OpaqueSerializer(); var c = new CacheValueCodec(r, s); var b = c.Encode(new Reply("opaque", 3), "reply.v1"); Assert.Equal(new Reply("opaque", 3), c.Decode(b)); s.Failure = new InvalidOperationException("programming"); Assert.Same(s.Failure, Assert.Throws<InvalidOperationException>(() => c.Decode(b))); s.Failure = new CacheValueDataException(CacheValueRejectionReason.MalformedBody); Assert.Same(s.Failure, Assert.Throws<CacheValueDataException>(() => c.Decode(b))); s.Failure = null; s.WrongType = true; Assert.Throws<InvalidOperationException>(() => c.Decode(b)); }
    [Fact] public void Maximum_Id_And_Invalid_Schema_Are_Bounded() { Assert.Throws<ArgumentException>(() => new CacheContractRegistry().RegisterContract(new string('x', 129), 1, TestJson.Default.Reply)); Assert.Throws<ArgumentOutOfRangeException>(() => new CacheContractRegistry().RegisterContract("valid", 0, TestJson.Default.Reply)); Assert.Throws<CacheValueDataException>(() => Codec().Decode(Frame("reply.v1", 0, "{}"))); var b = Frame("reply.v1", 1, "{}"); BinaryPrimitives.WriteUInt16BigEndian(b.AsSpan(5), ushort.MaxValue); Assert.Throws<CacheValueDataException>(() => Codec().Decode(b)); }
    internal static byte[] Frame(string id, int schema, string body) { var a = Encoding.UTF8.GetBytes(id); var payload = Encoding.UTF8.GetBytes(body); var b = new byte[11+a.Length+payload.Length]; "MRCV"u8.CopyTo(b); b[4]=1; BinaryPrimitives.WriteUInt16BigEndian(b.AsSpan(5), (ushort)a.Length); a.CopyTo(b,7); BinaryPrimitives.WriteInt32BigEndian(b.AsSpan(7+a.Length),schema); payload.CopyTo(b,11+a.Length); return b; }
    internal sealed class OpaqueSerializer : ICacheValueSerializer { public Exception? Failure { get; set; } public bool WrongType { get; set; } public string GetContractId(Type type) => "reply.v1"; public byte[] Serialize(object? value,string contractId) => [0xff, 0, 3]; public object? Deserialize(ReadOnlyMemory<byte> payload,string contractId) { if(Failure is not null) throw Failure; Assert.Equal(new byte[]{0xff,0,3},payload.ToArray()); return WrongType ? 42 : new Reply("opaque",3); } }
}
public sealed record Reply(string Value, int Number);
[JsonSerializable(typeof(Reply))] [JsonSerializable(typeof(int))] [JsonSerializable(typeof(int?))] [JsonSerializable(typeof(string))]
internal sealed partial class TestJson : JsonSerializerContext { }
